-- Keep programme names and unambiguous abbreviations searchable in sparse records.
-- BEGIN GENERATED TOPICS
on conflict(id) do update set label=excluded.label,pattern=excluded.pattern,version=excluded.version;
-- END GENERATED TOPICS

-- Catalogue provenance remains in the original record, outside retrieval text.
create or replace function public.research_clean_summary(value text) returns text language sql immutable strict set search_path='' as $$
 select case when value ~* 'Stage [0-9]+ inventory record|Item.level review has not yet been performed|Login or Register for Access|Username\(Required\).*Password|Hit enter to search or ESC to close'
 or btrim(value) in (
 'Publisher-listed resource. Metadata recorded for discovery; independent evidence appraisal pending.',
 'Public repository metadata entry. Eligibility and the underlying publication have not been verified.',
 'Resource identified in the official source listing. Content and evidence have not yet been independently appraised.'
 ) then ''
 else left(regexp_replace(regexp_replace(value,'<[^>]*>',' ','g'),'[[:space:]]+',' ','g'),3000) end;
$$;
-- Apply research_reindex in bounded batches after this migration. Existing valid
-- embeddings are retained; only records with changed representation are queued.
